// Files imported `with { type: "file" }`: the import is the file's path.
declare module "*.html" { const path: string; export default path }
declare module "*.png" { const path: string; export default path }
declare module "*.css" { const path: string; export default path }
declare module "*/app.js" { const path: string; export default path }
declare module "*/xterm.js" { const path: string; export default path }
declare module "*/addon-fit.js" { const path: string; export default path }
